-- GENERATED by `wfj generate` from data/gossip/gossip-f5.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["f50380244bff8657"] = { "Quando sarà il momento, mia signora. Tutto sarà chiaro quando sarà il momento. Il padrone si sta già risvegliando. Guarda ai cieli, perché la ⟦Brood of Nozdormu=Stirpe di Nozdormu⟧ è tornata.", "." },
  ["f5070ae8754e63c1"] = { "Ottima domanda, {class}. Le ultime notizie che ho avuto dicono che l'⟦Alliance=Alleanza⟧ era riuscita a fondere $1997w dei $1998w lingotti di rame, $2002w dei $2003w lingotti di ferro e $2011w dei $2012w lingotti di torio necessari per lo sforzo bellico.", "." },
  ["f50c040e11b7a57d"] = { "Hai imparato tutto ciò che posso insegnarti, {name}. È tempo che tu metta a frutto ciò che hai imparato qui e scelga un famiglio tutto tuo.\n\nEcco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come meglio credi. Usa le tue nuove abilità con orgoglio: te le sei guadagnate.", "." },
  ["f50e0dde4a062014"] = { "Mooranta può insegnarti la scuoiatura. La trovi appena fuori dagli armaioli di ⟦Thunder Bluff=Picco del Tuono⟧, sul terrazzo centrale.", "." },
  ["f51aa128e297e1bd"] = { "Il tuo spirito arde più luminoso di qualunque torcia io abbia mai visto, {name}, e per questo dovresti essere fier<o/a>.\n\nSe continuerai su questo cammino, gli elementi saranno ai tuoi ordini e i nostri fratelli si rivolgeranno a te in cerca di guida e saggezza. Lascia che sia il primo a congratularmi con te e a consegnarti il tuo nuovo totem.", "." },
  ["f51c64aafae72e4c"] = { "Buffo che tu lo chieda... Ho appena ricevuto un aggiornamento in proposito. Finora l'⟦Alliance=Alleanza⟧ ha raccolto $2060w dei $2061w pezzi di cuoio leggero, $2063w dei $2064w di cuoio medio e $2069w dei $2071w di cuoio spesso.", "." },
  ["f51e8d3396c29879"] = { "La tua tunica è pronta, {name}.", "." },
  ["f5320b953603b7b0"] = { "Attenti! Tutto il materiale bellico per ⟦Ahn'Qiraj=Ahn'qiraj⟧ è stato registrato ed è in corso di trasporto verso la ⟦Cenarion Hold=Fortezza Cenariana⟧, <signore/signora>! Mi dicono che l'ultimo carico dovrebbe arrivare in meno di $2113w giorni. Una volta fatto, e quando qualcuno suonerà quel gong laggiù per aprire i cancelli, garantisco che daremo a quegli insetti una battaglia coi fiocchi!", "." },
  ["f532949f52d40710"] = { "Abbiamo raccolto abbastanza pelli dai lupi. Presto la cavalleria sarà pronta a cavalcare! Parlami di nuovo quando avremo nelle stalle abbastanza arieti.", "." },
  ["f533bd13f2743bed"] = { "Come posso aiutarti nel tuo viaggio?", "." },
  ["f5367e4b7b73da17"] = { "Rovina profonda", "." },
  ["f53dea4e0237027e"] = { "L'E'ko è la forma dispersa del potere soprannaturale, e il Juju ne è l'essenza concentrata. Con un incantesimo potente, io posso trasformare l'E'ko in Juju. Quando diventa Juju, tu puoi usare la ⟦Cache of Mau'ari=Cassa di Mau'ari⟧ per riflettere quei poteri su di te.", "." },
  ["f55c5d42b7a92173"] = { "Papà! Sei tornato!", "." },
  ["f5628678fffdcb4f"] = { "Salute, {class}. Immagino tu sia qui per informarti sullo sforzo bellico per ⟦Ahn'Qiraj=Ahn'qiraj⟧. Avremo bisogno di moltissimo aiuto.\n\nLo sforzo bellico è un impegno comune dell'⟦Horde=Orda⟧ e dell'⟦Alliance=Alleanza⟧ per prepararsi all'imminente guerra contro i Silitidi e i loro padroni ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Nella ⟦Valley of Spirits=Valle degli Spiriti⟧ di Orgrimmar stiamo raccogliendo una grande quantità di merci per produrre materiale bellico, ed è per questi compiti di raccolta che ci serve il tuo aiuto.\n\nPosso convincerti a parlare con il nostro comandante per dare una mano?", "." },
  ["f56c162b07aaede1"] = { "E ora la guerra, lei sta per arrivare. Resta solo da spedire tutte queste merci e armi alla ⟦Cenarion Hold=Fortezza Cenariana⟧ a ⟦Silithus=Silitus⟧, e sarà fatto entro $2113w giorni. Poi qualche anima coraggiosa dovrà suonare il gong vicino alle porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧ per aprirle e far iniziare la guerra.", "." },
  ["f56d58cbf3c1f03d"] = { "Ti do il benvenuto, <fratello/sorella> <mio/mia>. Se sei qui per addestrarti, sarò felice di addestrarti.\n\nCorrono voci di discordia nel ⟦Cenarion Circle=Circolo Cenariano⟧, ma non dovresti dare retta a queste chiacchiere. Il nostro Arcidruido, Fandral Staghelm, guida noi e tutta Teldrassil verso la gloria!", "." },
  ["f56de0545868db09"] = { "Beh, forse \"pagare\" non è la parola migliore. Vedi, mentre stavo nella pancia di quella cosa, mi è venuta un'idea:\n\nQuesta creatura vive nel magma rovente e infuocato, eppure il fuoco non le fa nemmeno un graffio!\n\nSe solo potessi trovare una pelle intatta di una di queste bestie. Potrei portarla al mio caro amico, Malyfous Darkhammer, a ⟦Everlook=Lungavista⟧. Se qualcuno può fare qualcosa con la pelle di una bestia del genere, è lui.", "." },
  ["f57247c0e9bd90e7"] = { "{name}, ho creato il totem purificatore.", "." },
  ["f5736298f8b9ee50"] = { "Certo, ci mette di più a ricaricare, ma questo gioiellino ti apre un buco grande come il mio pugno in qualsiasi armatura.", "." },
  ["f5739fbd011b0243"] = { "Pescare è così piacevole, amico. Sai? Devo il mio stato di beatitudine al mio maestro, il più grande pescatore del mondo: Nat Pagle. Ne hai sentito parlare, amico?\n\nSe cerchi l'illuminazione, Nat Pagle è quello che ti mostrerà la via.", "." },
  ["f5810adbd97500eb"] = { "Ancora una volta hai fatto un buon lavoro, {name}. È da parecchio tempo che non vedo <un/una> giovane <stregone/strega> con il tuo potenziale. Ti assicuro che continuerò a seguire i tuoi progressi e a prepararti e assisterti nelle tue prove future.\n\nPer ora, lascia che ti mostri l'incantesimo per evocare la succube che hai appena dominato.", "." },
  ["f586e79f14893039"] = { "Teletrasportami al centro", "." },
  ["f58b2e34a6ac578a"] = { "Vaelastrasz, quando questo mondo apparterrà allo stormo nero, il tuo stormo conoscerà la sua fine.", "." },
  ["f58cfa5748517548"] = { "Sangue e anime per Hakkar! AHAHAHAH!", "." },
  ["f58d82f0f4c491b0"] = { "Prendi questo, bevilo tutto.", "." },
  ["f58f2133e6126d08"] = { "Lo eri. L'Occhio non sbaglia mai.\n\nDopotutto sei <un/una> <sacerdote/sacerdotessa>. <Un/Una> <sacerdote/sacerdotessa> potente, se l'Occhio ti ha mostrato questo orribile ricordo.\n\nSei <venuto/venuta> in cerca di redenzione, eppure nemmeno tu te ne rendi conto... vero?", "." },
  ["f59cff7a4bf58727"] = { "Ci sono 428.000 gradi Kraklenheit... Come va, bellezza?!", "." },
  ["f59f668670339dfb"] = { "La tua battaglia qui non è che il più piccolo granello di un'invasione mondiale, cucciolo! È ora che tu conosca i poteri che affronti!", "." },
  ["f5a1c3656f8dee8a"] = { "Cosa ci fai qui fuori?", "." },
  ["f5a4711844ed5a7e"] = { "Imbarco per il trasporto verso la città di Dalaran, situata nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "." },
  ["f5a72f36a1a99c8e"] = { "Notate la debole struttura di legame di questo. Assicuratevi di completare i vostri incantesimi, o questo è ciò che otterrete.", "." },
  ["f5abb388b78855b0"] = { "Oh, cielo, che sorpresa! Un altro fallimento!? Ma come, o grande??", "." },
  ["f5b2ee6b6f6bae14"] = { "Hai l'aria sicura di te. Di certo non ti dispiacerà mettere alla prova le tue abilità?", "." },
  ["f5b978bdbbc4521e"] = { "{name}, i miei doveri sono compiuti e ora prenderò congedo. Buona fortuna, <amico/amica> <mio/mia>, e ricorda di mantenere in funzione la Campana, la Ruota e la Candela!", "." },
  ["f5be96ca8cdebdb3"] = { "Khan Hratha è morto! Ora i Magram sono i più forti tra i centauri! Schiacceremo gli altri e domineremo ⟦Desolace=Desolanda⟧!\n\nCi ricorderemo di te, {name}, e i nostri zoccoli ti risparmieranno quando tutti gli altri saranno calpestati.", "." },
  ["f5bec52007ff9685"] = { "%s sospira...", "." },
  ["f5cf13e5ef7bcd29"] = { "Furono l'alto generale Abbendis, il sommo inquisitore Isillien e il gran signore Mograine a fondare la Crociata. Agli inizi, la Crociata era un ordine nobile. La follia e il fanatismo insensato che vedi ora non esistevano. Fu solo con la comparsa di colui che è noto come il Gran Crociato che gli ingranaggi della corruzione si misero in moto.", "." },
  ["f5d26f82c26f8e7c"] = { "{class}, non ci vergogniamo di dire che abbiamo bisogno di tutto l'aiuto possibile nella nostra lotta alla ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Ma ora c'è più onore da conquistare che mai in passato, se scegli di prestarci le tue abilità. Inoltre, le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ guarderanno di certo con maggior favore ciò che farai per noi. Ti unirai alla battaglia?", "." },
  ["f5deca345165a6dc"] = { "L'incubo finirà mai?! Non riesco a costringermi a svegliarmi!", "." },
  ["f5eb8d533ee0b7dd"] = { "Salute, {class}. È bello vedere che ti interessa aiutare lo sforzo bellico. I raccoglitori qui stanno organizzando la raccolta di varie scorte di merci, così da essere pronti quando arriverà il momento.\n\nIo mi occupo di procurare $2106w salmoni impanati da mettere da parte per chi combatterà ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. L'ultima volta che ho contato, ne avevamo raccolti $2105w.", "." },
  ["f5ee7552a36bc30b"] = { "Per lo più il solito. Attacchi dei murloc, qualche scaramuccia con la ⟦Scarlet Crusade=Crociata Scarlatta⟧. Ci sono perfino dei paladini che non riescono proprio ad abituarsi alla vita da Reietti. Troppo spesso dobbiamo abbattere quelli che rivolgono le lame contro i loro fratelli.\n\nDi gran lunga il peggio è quando qualche servo senza mente si avvicina troppo. Posso uccidere murloc tutto il giorno, ma alcuni membri del Flagello che ho dovuto distruggere erano miei vecchi amici. Alcuni erano perfino miei familiari.\n\nPreferisco essere io ad abbatterli piuttosto che un avventuriero qualunque, ma fa comunque male.", "." },
  ["f5f4190a7d71d4e2"] = { "Hai mai sentito parlare di un posto chiamato ⟦Dire Maul=Maglio Infausto⟧?", "." },
  ["f5f9b8d891b84a71"] = { "Okay, <fratello/sorella>, ora tocca alla sapta... stammi vicino.", "." },
  ["f5fbb234b3f530dc"] = { "Ho molto sapere da trasmetterti, {class}. Devi imparare a cacciare con onore.", "." },
})
